{
    "single_choice_questions": [
        {
            "question": "Given a DataFrame `labeled` with rows indexed by channel names (e.g., 'Email', 'Social', 'Search', 'Display'), what does `labeled.iloc[2, 0]` return?",
            "options": [
                "The value at the row with integer position 2 and the first column, regardless of labels",
                "The value in the row labeled '2' and the column named '0'",
                "The value in the row labeled 'Search' and the first column, because .iloc uses labels",
                "A KeyError, because .iloc cannot be used with two arguments"
            ],
            "correct_option": 0,
            "explanation": "`.iloc` selects strictly by integer position: row position 2 (the third row) and column position 0 (the first column). Label-based selection would use `.loc['Search', 'spend']` instead."
        },
        {
            "question": "Which pair of methods gives you the quickest answer to 'which columns have missing data, and what are their dtypes?' when you first inspect a loaded CSV?",
            "options": [
                "`.info()` and `.isnull().sum()`",
                "`.head()` and `.describe()`",
                "`.value_counts()` and `.duplicated().sum()`",
                "`.shape` and `.columns`"
            ],
            "correct_option": 0,
            "explanation": "`.info()` shows each column's Non-Null Count and dtype in one call, and `.isnull().sum()` gives exact missing counts per column. This matches Steps 3 and 5 of the first-pass exploration workflow."
        },
        {
            "question": "You want campaigns with spend over 1000, showing only `channel` and `conversions`. Which single line is the recommended pattern from the document?",
            "options": [
                "`campaigns.loc[campaigns['spend'] > 1000, ['channel', 'conversions']]`",
                "`campaigns['channel', 'conversions'][campaigns['spend'] > 1000]`",
                "`campaigns[(campaigns['spend'] > 1000) and (campaigns['channel'])]`",
                "`campaigns.iloc[campaigns['spend'] > 1000, ['channel', 'conversions']]`"
            ],
            "correct_option": 0,
            "explanation": "`df.loc[mask, columns]` is the signature pattern for filtering rows and selecting columns in one safe step. Chained indexing risks SettingWithCopyWarning, `and` raises a ValueError in masks, and `.iloc` does not accept boolean masks combined with column names this way."
        }
    ],
