    "true_false_questions": [
        {
            "question": "In pandas, `campaigns.loc['C1':'C3']` includes the row labeled 'C3', while `campaigns.iloc[0:3]` excludes the row at position 3.",
            "correct_answer": true,
            "explanation": "This is a key gotcha: `.loc` slices are inclusive of the end label, while `.iloc` slices follow Python's exclusive-end convention, so `0:3` returns rows at positions 0, 1, and 2 only."
        }
